package com.linkplay.app;
import android.content.*; import android.graphics.*; import android.graphics.drawable.GradientDrawable; import android.net.Uri; import android.os.Bundle; import android.view.Gravity; import android.view.inputmethod.InputMethodManager; import android.widget.*; import androidx.appcompat.app.AppCompatActivity; import com.google.android.material.button.MaterialButton; import com.google.android.material.textfield.TextInputEditText;
public class MainActivity extends AppCompatActivity {
 TextInputEditText input; TextView status; final int bg=0xFF07111F,panel=0xFF0F1F31,green=0xFF10B981,white=0xFFF1F5F9,muted=0xFF94A3B8;
 public void onCreate(Bundle b){super.onCreate(b);getWindow().setStatusBarColor(bg);getWindow().setNavigationBarColor(bg);ui();handle(getIntent());}
 protected void onNewIntent(Intent i){super.onNewIntent(i);setIntent(i);handle(i);}
 GradientDrawable shape(int c,int r){GradientDrawable d=new GradientDrawable();d.setColor(c);d.setCornerRadius(r);d.setStroke(1,0xFF233649);return d;}
 int dp(float n){return (int)(n*getResources().getDisplayMetrics().density+.5f);}
 void ui(){ScrollView s=new ScrollView(this);LinearLayout root=new LinearLayout(this);root.setOrientation(1);root.setPadding(dp(22),dp(30),dp(22),dp(24));root.setBackgroundColor(bg);s.addView(root);setContentView(s);
 TextView logo=new TextView(this);logo.setText("LINKPLAY");logo.setTextColor(green);logo.setTextSize(13);logo.setLetterSpacing(.18f);logo.setTypeface(null,1);root.addView(logo);
 TextView title=new TextView(this);title.setText("شغّل الرابط، لا تحمّله");title.setTextColor(white);title.setTextSize(27);title.setGravity(Gravity.RIGHT);title.setTypeface(null,1);LinearLayout.LayoutParams tl=new LinearLayout.LayoutParams(-1,-2);tl.topMargin=dp(26);root.addView(title,tl);
 TextView sub=new TextView(this);sub.setText("ألصق رابط GitHub للفيديو، أو شاركه إلى LinkPlay، ثم اختر طريقة التشغيل.");sub.setTextColor(muted);sub.setTextSize(15);sub.setGravity(Gravity.RIGHT);sub.setLineSpacing(dp(4),1);LinearLayout.LayoutParams sl=new LinearLayout.LayoutParams(-1,-2);sl.topMargin=dp(9);root.addView(sub,sl);
 LinearLayout card=new LinearLayout(this);card.setOrientation(1);card.setPadding(dp(16),dp(18),dp(16),dp(18));card.setBackground(shape(panel,dp(18)));LinearLayout.LayoutParams cl=new LinearLayout.LayoutParams(-1,-2);cl.topMargin=dp(28);root.addView(card,cl);
 TextView label=new TextView(this);label.setText("رابط الفيديو");label.setTextColor(white);label.setTextSize(15);label.setGravity(Gravity.RIGHT);label.setTypeface(null,1);card.addView(label);
 input=new TextInputEditText(this);input.setTextColor(white);input.setHintTextColor(muted);input.setHint("https://github.com/.../video.mp4");input.setTextSize(13);input.setMinLines(2);input.setGravity(Gravity.RIGHT|Gravity.TOP);input.setPadding(dp(12),dp(12),dp(12),dp(12));input.setBackground(shape(0xFF081524,dp(12)));LinearLayout.LayoutParams il=new LinearLayout.LayoutParams(-1,-2);il.topMargin=dp(12);card.addView(input,il);
 MaterialButton paste=button("لصق الرابط",0xFF233649,white);LinearLayout.LayoutParams pl=new LinearLayout.LayoutParams(-1,dp(48));pl.topMargin=dp(12);card.addView(paste,pl);paste.setOnClickListener(v->paste());
 MaterialButton play=button("تشغيل داخل التطبيق",green,0xFF031914);LinearLayout.LayoutParams p2=new LinearLayout.LayoutParams(-1,dp(52));p2.topMargin=dp(16);root.addView(play,p2);play.setOnClickListener(v->internal());
 MaterialButton ext=button("فتح بمشغّل خارجي",0xFF233649,white);LinearLayout.LayoutParams p3=new LinearLayout.LayoutParams(-1,dp(50));p3.topMargin=dp(10);root.addView(ext,p3);ext.setOnClickListener(v->external());
 status=new TextView(this);status.setText("يدعم روابط ملفات الفيديو العامة، ومنها GitHub Releases.");status.setTextColor(muted);status.setTextSize(13);status.setGravity(Gravity.RIGHT);status.setLineSpacing(dp(3),1);LinearLayout.LayoutParams st=new LinearLayout.LayoutParams(-1,-2);st.topMargin=dp(20);root.addView(status,st);
 TextView note=new TextView(this);note.setText("ملاحظة: نجاح التشغيل يعتمد على صلاحية الرابط ودعم الخادم للبث. بعض الملفات قد لا تعمل مباشرة إذا كان الخادم يفرض التنزيل.");note.setTextColor(muted);note.setTextSize(12);note.setGravity(Gravity.RIGHT);note.setLineSpacing(dp(3),1);LinearLayout.LayoutParams nl=new LinearLayout.LayoutParams(-1,-2);nl.topMargin=dp(18);root.addView(note,nl);}
 MaterialButton button(String t,int color,int fg){MaterialButton b=new MaterialButton(this);b.setText(t);b.setTextColor(fg);b.setBackgroundTintList(android.content.res.ColorStateList.valueOf(color));return b;}
 void handle(Intent i){if(i==null)return;String v=null;if(Intent.ACTION_SEND.equals(i.getAction()))v=i.getStringExtra(Intent.EXTRA_TEXT);else if(Intent.ACTION_VIEW.equals(i.getAction())&&i.getData()!=null)v=i.getData().toString();String u=extract(v);if(u!=null&&input!=null){input.setText(u);status.setText("تم استلام الرابط. اختر طريقة التشغيل.");}}
 String extract(String t){if(t==null)return null;java.util.regex.Matcher m=java.util.regex.Pattern.compile("https?://[^\\s<>\\\"']+").matcher(t.trim());return m.find()?m.group().replaceAll("[),.]+$",""):null;}
 String valid(){String raw=input.getText()==null?"":input.getText().toString().trim(),u=extract(raw);if(u==null){status.setText("ألصق رابط HTTPS صحيحاً أولاً.");return null;}Uri x=Uri.parse(u);String h=x.getHost();if(!"https".equalsIgnoreCase(x.getScheme())||h==null||!(h.equalsIgnoreCase("github.com")||h.endsWith("githubusercontent.com"))){status.setText("أدخل رابط GitHub أو رابط ملف GitHub المباشر.");return null;}if(!u.toLowerCase().matches(".*\\.(mp4|m4v|webm|mov)(\\?.*)?$")){status.setText("تأكد أن الرابط ينتهي بامتداد فيديو مثل MP4 أو WebM.");return null;}return u;}
 void internal(){String u=valid();if(u==null)return;((InputMethodManager)getSystemService(INPUT_METHOD_SERVICE)).hideSoftInputFromWindow(input.getWindowToken(),0);Intent i=new Intent(this,PlayerActivity.class);i.putExtra("url",u);startActivity(i);}
 void external(){String u=valid();if(u==null)return;Intent i=new Intent(Intent.ACTION_VIEW);i.setDataAndType(Uri.parse(u),"video/*");try{startActivity(Intent.createChooser(i,"اختيار مشغّل الفيديو"));}catch(Exception e){status.setText("ماكو مشغّل خارجي مناسب مثبت.");}}
 void paste(){android.content.ClipboardManager c=(android.content.ClipboardManager)getSystemService(CLIPBOARD_SERVICE);if(c!=null&&c.hasPrimaryClip()&&c.getPrimaryClip().getItemCount()>0){CharSequence v=c.getPrimaryClip().getItemAt(0).coerceToText(this);String u=extract(v==null?"":v.toString());if(u!=null){input.setText(u);status.setText("تم لصق الرابط. اختر طريقة التشغيل.");}else status.setText("الحافظة لا تحتوي على رابط صالح.");}else status.setText("الحافظة فارغة.");}
}
